import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, AdditiveBlending } = ctx.THREE;

  const colors =
    config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const root = new Group();
  root.name = 'journal-card-2-label';

  const inner = new Group();
  root.add(inner);

  // ---- card plane (atlas aspect 512x320 = 1.6) ----
  const planeW = 2.8;
  const planeH = 1.75;
  const planeGeo = new PlaneGeometry(planeW, planeH);
  const cardMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    opacity: 1.0,
  });

  // base color tint until texture loads — keep dark surface so flat-void is avoided
  cardMat.color = new Color(surface);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.anisotropy = 4;
      cardMat.map = tex;
      cardMat.color = new Color('#ffffff');
      cardMat.needsUpdate = true;
    });
  }

  const card = new Mesh(planeGeo, cardMat);
  card.position.z = 0;
  inner.add(card);

  // ---- accent edge strip on the left ----
  const edgeGeo = new PlaneGeometry(0.07, planeH);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(accent),
    transparent: true,
    toneMapped: false,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(-planeW / 2 + 0.035, 0, 0.002);
  inner.add(edge);

  // ---- thin paper-tinted sheen strip across top for depth ----
  const sheenGeo = new PlaneGeometry(planeW, 0.04);
  const sheenMat = new MeshBasicNodeMaterial({
    color: new Color(paper),
    transparent: true,
    opacity: 0.12,
    toneMapped: false,
  });
  const sheen = new Mesh(sheenGeo, sheenMat);
  sheen.position.set(0, planeH / 2 - 0.02, 0.0015);
  inner.add(sheen);

  // ---- text overlay: "Journal 2" headline ----
  let headlineText = items.find((i) => i.role === 'headline')?.text;
  if (!headlineText && items.length) headlineText = items[0].text;
  if (!headlineText) headlineText = 'Journal 2';

  const fontSize =
    items.find((i) => i.role === 'headline')?.typography?.fontSize ?? 39;

  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize,
    color: paper,
    align: 'left',
  });
  headline.position.set(-planeW / 2 + 0.28, planeH / 2 - 0.42, 0.003);
  inner.add(headline);

  // ---- caption-style index marker ----
  const indexLabel = ctx.fontAtlas.createText('JOURNAL / 02', {
    fontSize: 14,
    color: accent,
    align: 'left',
  });
  indexLabel.position.set(-planeW / 2 + 0.28, -planeH / 2 + 0.28, 0.003);
  inner.add(indexLabel);

  // ---- primitive: parallax-scroll (scroll-triggered) ----
  const primitiveResults = [];
  for (const p of config.cinematicPrimitives ?? []) {
    if (!ctx.primitives || !ctx.primitives[p.name]) continue;
    try {
      const r = ctx.primitives[p.name](inner, p.params ?? {});
      if (r) primitiveResults.push(r);
    } catch (_) {}
  }

  // ---- entrance timeline: rise-in + weighted-settle ----
  const tl = gsap.timeline();
  inner.position.y = 0.4;
  inner.position.z = 0.0;
  inner.scale.set(0.96, 0.96, 0.96);
  tl.to(inner.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  })
    .to(
      inner.scale,
      { x: 1.04, y: 1.04, z: 1.04, duration: 0.55, ease: 'power4.out' },
      '<'
    )
    .to(
      inner.scale,
      { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
      '-=0.25'
    );

  // ---- edge.Focus -> ease in the accent edge
  edge.scale.x = 0.25;
  tl.to(
    edge.scale,
    { x: 1, duration: 0.7, ease: 'power3.out' },
    '-=0.6'
  );

  // ---- interactions ----
  const hoverState = { active: false };
  const handlers = {
    onPointerEnter: () => {
      hoverState.active = true;
      gsap.to(inner.position, {
        y: 0.15,
        duration: 0.6,
        ease: 'power3.out',
        overwrite: 'auto',
      });
      gsap.to(edgeMat, {
        opacity: 1,
        duration: 0.35,
        ease: 'power2.out',
        overwrite: 'auto',
      });
      gsap.to(sheenMat, {
        opacity: 0.25,
        duration: 0.4,
        ease: 'power2.out',
        overwrite: 'auto',
      });
    },
    onPointerLeave: () => {
      hoverState.active = false;
      gsap.to(inner.position, {
        y: 0,
        duration: 0.5,
        ease: 'power2.out',
        overwrite: 'auto',
      });
      gsap.to(edgeMat, {
        opacity: 0.85,
        duration: 0.4,
        ease: 'power2.out',
        overwrite: 'auto',
      });
      gsap.to(sheenMat, {
        opacity: 0.12,
        duration: 0.4,
        ease: 'power2.out',
        overwrite: 'auto',
      });
    },
    onClick: () => {
      const press = gsap.timeline();
      press
        .to(inner.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'power2.in',
        })
        .to(inner.scale, {
          x: 1.0,
          y: 1.0,
          z: 1.0,
          duration: 0.5,
          ease: 'back.out(2.2)',
        });
      ctx.emit('hub-journal.select', { id: 'journal-2', source: 'card-label' });
    },
  };

  // prep accent edge base opacity
  edgeMat.opacity = 0.85;

  root.userData.handlers = handlers;

  root.userData.cleanup = () => {
    tl.kill();
    hoverState.active = false;
    planeGeo.dispose();
    cardMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    sheenGeo.dispose();
    sheenMat.dispose();
    for (const r of primitiveResults) r.cleanup?.();
    gsap.killTweensOf(inner.position);
    gsap.killTweensOf(inner.scale);
    gsap.killTweensOf(edgeMat);
    gsap.killTweensOf(sheenMat);
  };

  return root;
}
